create or replace function platform_private.has_permission_for(
  p_user_id uuid,p_permission_code text,p_scope_type text,p_scope_id uuid
) returns boolean language sql stable security definer set search_path='' as $$
  select platform_private.is_account_approved(p_user_id)
    and platform_private.validated_phase1c_device_authorization(
      p_user_id,platform_private.phase1c_context_device_id()
    ) is not null
    and p_scope_type='platform' and p_scope_id is null
    and exists(select 1 from platform.user_roles assignment
      join platform.roles role on role.id=assignment.role_id
      join platform.role_permissions role_permission on role_permission.role_id=role.id
      join platform.permissions permission on permission.id=role_permission.permission_id
      where assignment.user_id=p_user_id and assignment.scope_type='platform' and assignment.scope_id is null
        and assignment.revoked_at is null and (assignment.expires_at is null or assignment.expires_at>pg_catalog.now())
        and role.scope_type='platform' and role.domain='platform' and permission.domain='platform'
        and permission.code=p_permission_code);
$$;

create or replace function platform.has_permission(
  p_permission_code text,p_scope_type text default 'platform',p_scope_id uuid default null
) returns boolean language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and p_scope_type='platform'
    and platform_private.has_permission_for(auth.uid(),p_permission_code,p_scope_type,p_scope_id);
$$;

-- There is no runtime caller for this routine. It reports account/role metadata
-- only and explicitly makes no claim about device possession or permissions.
create or replace function platform.get_my_access_context(
  p_domain text default 'platform',p_scope_type text default 'platform',p_scope_id uuid default null
) returns jsonb language sql stable security definer set search_path='' as $$
  select case when auth.uid() is null then null else pg_catalog.jsonb_build_object(
    'userId',auth.uid(),'displayName',profile.display_name,'avatarUrl',profile.avatar_url,
    'accountStatus',coalesce(profile.account_status,'pending'),'deviceStatus','not_asserted',
    'deviceLifecycle','not_asserted','possessionVerified',false,
    'roles',coalesce((select pg_catalog.jsonb_agg(role.code order by role.code)
      from platform.user_roles assignment join platform.roles role on role.id=assignment.role_id
      where assignment.user_id=auth.uid() and p_domain='platform' and p_scope_type='platform' and p_scope_id is null
        and role.domain='platform' and role.scope_type='platform' and assignment.scope_type='platform'
        and assignment.scope_id is null and assignment.revoked_at is null
        and (assignment.expires_at is null or assignment.expires_at>pg_catalog.now())),'[]'::jsonb),
    'permissions','[]'::jsonb
  ) end from (select 1) singleton left join platform.profiles profile on profile.user_id=auth.uid();
$$;

create or replace function platform.grant_user_role(
  p_user_id uuid,p_role_domain text,p_role_code text,p_scope_type text,p_scope_id uuid default null
) returns uuid language plpgsql security definer set search_path='' as $$
declare target_role platform.roles%rowtype; assignment_id uuid; actor_authorization_id uuid;
begin
  if not platform_private.has_permission_for(auth.uid(),'platform.roles.manage','platform',null) then
    raise exception 'PERMISSION_DENIED' using errcode='42501';
  end if;
  actor_authorization_id:=platform_private.validated_phase1c_device_authorization(
    auth.uid(),platform_private.phase1c_context_device_id());
  if actor_authorization_id is null then raise exception 'DEVICE_SESSION_REQUIRED' using errcode='42501'; end if;
  if p_role_domain='inventory' or p_scope_type='inventory' then
    raise exception 'INVENTORY_AUTHORITY_RETIRED' using errcode='42501';
  end if;
  if p_scope_type<>'platform' or p_scope_id is not null then
    raise exception 'UNSUPPORTED_ROLE_SCOPE' using errcode='22023';
  end if;
  select * into target_role from platform.roles where domain=p_role_domain and code=p_role_code;
  if not found or target_role.scope_type<>p_scope_type then raise exception 'ROLE_NOT_FOUND_OR_SCOPE_INVALID' using errcode='P0002'; end if;
  if not target_role.is_assignable then raise exception 'ROLE_NOT_ASSIGNABLE' using errcode='42501'; end if;
  if not exists(select 1 from platform.profiles where user_id=p_user_id) then raise exception 'PROFILE_NOT_FOUND' using errcode='P0002'; end if;
  select id into assignment_id from platform.user_roles where user_id=p_user_id and role_id=target_role.id
    and scope_type=p_scope_type and scope_id is null and revoked_at is null;
  if assignment_id is null then
    insert into platform.user_roles(user_id,role_id,scope_type,scope_id,granted_by)
    values(p_user_id,target_role.id,p_scope_type,null,auth.uid()) returning id into assignment_id;
    insert into platform.audit_events(actor_user_id,actor_device_authorization_id,subject_user_id,domain,module,action,
      entity_type,entity_id,scope_type,old_values,new_values,metadata,source)
    values(auth.uid(),actor_authorization_id,p_user_id,'platform','roles','role.granted','user_role',assignment_id,
      p_scope_type,null,pg_catalog.jsonb_build_object('domain',p_role_domain,'role',p_role_code),
      '{}'::jsonb,'device_session_dispatcher');
  end if;
  return assignment_id;
end;
$$;

revoke all on function platform_private.has_permission_for(uuid,text,text,uuid),platform.get_my_access_context(text,text,uuid),platform.grant_user_role(uuid,text,text,text,uuid) from public,anon,authenticated,service_role;
revoke all on function platform.has_permission(text,text,uuid) from public,anon,authenticated,service_role;
grant execute on function platform.has_permission(text,text,uuid) to authenticated;

do $$
begin
  if exists(select 1 from platform.roles where domain='inventory'
    and code in ('inventory_manager','inventory_operator','viewer') and is_assignable) then
    raise exception 'INVENTORY_AUTHORITY_RETIREMENT_INCOMPLETE' using errcode='55000';
  end if;
end;
$$;

commit;

-- Require foundation module access before non-owner business authority and prevent transitive module-manager delegation.

create or replace function public.require_effective_module_permission(
  p_actor_device_id uuid,
  p_module_key text,
  p_permission_key text,
  p_resource_type text default null,
  p_resource_id text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  actor_id uuid;
  catalog_context jsonb;
  matching_grant public.module_permission_grants%rowtype;
begin
  actor_id := public.require_current_approved_device(p_actor_device_id);
  catalog_context := public.validate_module_permission_catalog(
    p_module_key, p_permission_key, p_resource_type, p_resource_id, 'authorize'
  );

  if public.is_system_owner(actor_id) then
    return jsonb_build_object(
      'actorUserId', actor_id,
      'actorDeviceId', p_actor_device_id,
      'moduleKey', p_module_key,
      'permissionKey', p_permission_key,
      'resourceType', p_resource_type,
      'resourceId', p_resource_id,
      'authoritySource', 'system_owner',
      'grantId', null,
      'catalogVersion', (catalog_context ->> 'catalogVersion')::integer
    );
  end if;

  perform public.require_module_permission(
    p_actor_device_id, p_module_key, 'module.access', null, null
  );

  matching_grant := null;
  if p_resource_type is not null then
    select * into matching_grant
      from public.module_permission_grants as grants
     where grants.user_id = actor_id
       and grants.module_key = p_module_key
       and grants.permission_key = p_permission_key
       and grants.resource_type = p_resource_type
       and grants.resource_id = p_resource_id
       and grants.revoked_at is null
     limit 1;
  end if;

  if matching_grant.grant_id is null then
    select * into matching_grant
      from public.module_permission_grants as grants
     where grants.user_id = actor_id
       and grants.module_key = p_module_key
       and grants.permission_key = p_permission_key
       and grants.resource_type is null
       and grants.resource_id is null
       and grants.revoked_at is null
     limit 1;
  end if;

  if matching_grant.grant_id is null then
    raise exception 'MODULE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'actorUserId', actor_id,
    'actorDeviceId', p_actor_device_id,
    'moduleKey', p_module_key,
    'permissionKey', p_permission_key,
    'resourceType', p_resource_type,
    'resourceId', p_resource_id,
    'authoritySource', case
      when matching_grant.resource_type is null then 'module_grant'
      else 'resource_grant'
    end,
    'grantId', matching_grant.grant_id,
    'catalogVersion', (catalog_context ->> 'catalogVersion')::integer
  );
end;
$$;

create or replace function public.manage_foundation_module_grant(
  p_actor_device_id uuid,
  p_operation_id uuid,
  p_action text,
  p_target_user_id uuid,
  p_module_key text,
  p_permission_key text,
  p_grant_id uuid default null,
  p_revocation_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  actor_id uuid;
  revalidated_actor_id uuid;
  authority_context jsonb;
  authority_source text;
  authority_grant_id uuid;
  intent text;
  target_status text;
  prior_operation public.module_grant_operations%rowtype;
  target_grant public.module_permission_grants%rowtype;
  existing_grant public.module_permission_grants%rowtype;
  result_grant_id uuid;
  result_status text;
  result jsonb;
  old_values jsonb;
  new_values jsonb;
  active_non_owner_manager_count bigint;
begin
  if p_operation_id is null or p_target_user_id is null
     or p_module_key is null
     or p_permission_key not in ('module.access', 'module.manage')
     or p_action not in ('create', 'revoke')
     or (p_action = 'create' and (p_grant_id is not null or p_revocation_reason is not null))
     or (p_action = 'revoke' and p_grant_id is null)
     or (
       p_revocation_reason is not null
       and (
         char_length(btrim(p_revocation_reason)) not between 1 and 500
         or p_revocation_reason <> btrim(p_revocation_reason)
       )
     ) then
    raise exception 'INVALID_FOUNDATION_GRANT_OPERATION' using errcode = '22023';
  end if;

  actor_id := public.require_current_approved_device(p_actor_device_id);
  if not exists (
    select 1 from public.platform_modules as modules
     where modules.module_key = p_module_key and modules.status = 'active'
  ) then
    raise exception 'ACTIVE_MODULE_REQUIRED' using errcode = '42501';
  end if;

  if p_permission_key = 'module.manage' then
    if not public.is_system_owner(actor_id) then
      raise exception 'SYSTEM_OWNER_REQUIRED' using errcode = '42501';
    end if;
    authority_source := 'system_owner';
    authority_grant_id := null;
  elsif public.is_system_owner(actor_id) then
    authority_source := 'system_owner';
    authority_grant_id := null;
  else
    authority_context := public.require_module_permission(
      p_actor_device_id, p_module_key, 'module.manage', null, null
    );
    authority_source := 'module_grant';
    authority_grant_id := (authority_context ->> 'grantId')::uuid;
  end if;

  if p_action = 'create' and actor_id = p_target_user_id then
    raise exception 'MODULE_GRANT_SELF_GRANT_PROHIBITED' using errcode = '42501';
  end if;

  intent := encode(extensions.digest(
    jsonb_build_object(
      'action', p_action,
      'actorUserId', actor_id,
      'actorDeviceId', p_actor_device_id,
      'targetUserId', p_target_user_id,
      'moduleKey', p_module_key,
      'permissionKey', p_permission_key,
      'resourceType', null,
      'resourceId', null,
      'grantId', p_grant_id,
      'revocationReason', p_revocation_reason
    )::text,
    'sha256'
  ), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended('module-grant-operation:' || p_operation_id::text, 0)
  );
  select * into prior_operation
    from public.module_grant_operations as operations
   where operations.operation_id = p_operation_id;
  if found then
    if prior_operation.intent_hash = intent then
      return prior_operation.stored_result;
    end if;
    raise exception 'MODULE_GRANT_OPERATION_MISMATCH' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('module-managers:' || p_module_key, 0)
  );

  revalidated_actor_id := public.require_current_approved_device(p_actor_device_id);
  if revalidated_actor_id <> actor_id then
    raise exception 'MODULE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;
  if p_permission_key = 'module.manage' then
    if authority_source <> 'system_owner' or not public.is_system_owner(actor_id) then
      raise exception 'SYSTEM_OWNER_REQUIRED' using errcode = '42501';
    end if;
  elsif authority_source = 'system_owner' then
    if not public.is_system_owner(actor_id) then
      raise exception 'SYSTEM_OWNER_REQUIRED' using errcode = '42501';
    end if;
  elsif not exists (
    select 1 from public.module_permission_grants as grants
     where grants.grant_id = authority_grant_id
       and grants.user_id = actor_id
       and grants.module_key = p_module_key
       and grants.permission_key = 'module.manage'
       and grants.resource_type is null
       and grants.resource_id is null
       and grants.revoked_at is null
  ) then
    raise exception 'MODULE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('module-grant:' || p_module_key || ':' || p_target_user_id::text, 0)
  );

  if p_action = 'create' then
    if not exists (select 1 from auth.users as users where users.id = p_target_user_id) then
      raise exception 'TARGET_ACCOUNT_NOT_FOUND' using errcode = 'P0002';
    end if;
    target_status := null;
    select access.account_status into target_status
      from public.system_user_access as access
     where access.user_id = p_target_user_id
     for update;
    if target_status is distinct from 'approved' then
      raise exception 'TARGET_ACCOUNT_APPROVED_REQUIRED' using errcode = '42501';
    end if;

    select * into existing_grant
      from public.module_permission_grants as grants
     where grants.user_id = p_target_user_id
       and grants.module_key = p_module_key
       and grants.permission_key = p_permission_key
       and grants.resource_type is null
       and grants.resource_id is null
       and grants.revoked_at is null
     for update;
    if found then
      result_grant_id := existing_grant.grant_id;
      result_status := 'existing';
      result := jsonb_build_object(
        'status', result_status, 'grantId', result_grant_id,
        'targetUserId', p_target_user_id, 'moduleKey', p_module_key,
        'permissionKey', p_permission_key, 'resourceType', null, 'resourceId', null
      );
    else
      insert into public.module_permission_grants (
        user_id, module_key, permission_key, granted_by, granted_by_device_id
      ) values (
        p_target_user_id, p_module_key, p_permission_key, actor_id, p_actor_device_id
      ) returning grant_id into result_grant_id;
      result_status := 'created';
      old_values := '{}'::jsonb;
      new_values := jsonb_build_object(
        'active', true, 'permissionKey', p_permission_key,
        'resourceType', null, 'resourceId', null
      );
      result := jsonb_build_object(
        'status', result_status, 'grantId', result_grant_id,
        'targetUserId', p_target_user_id, 'moduleKey', p_module_key,
        'permissionKey', p_permission_key, 'resourceType', null, 'resourceId', null
      );
    end if;
  else
    select * into target_grant
      from public.module_permission_grants as grants
     where grants.grant_id = p_grant_id
     for update;
    if not found
       or target_grant.user_id <> p_target_user_id
       or target_grant.module_key <> p_module_key
       or target_grant.permission_key <> p_permission_key
       or target_grant.resource_type is not null
       or target_grant.resource_id is not null then
      raise exception 'MODULE_GRANT_NOT_FOUND_OR_STALE' using errcode = 'P0002';
    end if;

    result_grant_id := target_grant.grant_id;
    if target_grant.revoked_at is not null then
      result_status := 'already_revoked';
      result := jsonb_build_object(
        'status', result_status, 'grantId', result_grant_id,
        'targetUserId', p_target_user_id, 'moduleKey', p_module_key,
        'permissionKey', p_permission_key, 'resourceType', null, 'resourceId', null
      );
    else
      if authority_source = 'module_grant'
         and actor_id = p_target_user_id
         and p_permission_key = 'module.manage' then
        raise exception 'MODULE_MANAGER_SELF_REVOCATION_PROHIBITED' using errcode = '42501';
      end if;

      if p_permission_key = 'module.manage'
         and not public.is_system_owner(p_target_user_id) then
        select count(*) into active_non_owner_manager_count
          from public.module_permission_grants as grants
         where grants.module_key = p_module_key
           and grants.permission_key = 'module.manage'
           and grants.resource_type is null
           and grants.resource_id is null
           and grants.revoked_at is null
           and not public.is_system_owner(grants.user_id);
        if active_non_owner_manager_count <= 1 then
          raise exception 'LAST_MODULE_MANAGER_REVOCATION_PROHIBITED' using errcode = '42501';
        end if;
      end if;

      old_values := jsonb_build_object(
        'active', true, 'permissionKey', target_grant.permission_key,
        'resourceType', null, 'resourceId', null
      );
      update public.module_permission_grants
         set revoked_at = now(), revoked_by = actor_id,
             revoked_by_device_id = p_actor_device_id,
             revocation_reason = p_revocation_reason
       where grant_id = result_grant_id;
      result_status := 'revoked';
      new_values := jsonb_build_object(
        'active', false, 'permissionKey', target_grant.permission_key,
        'resourceType', null, 'resourceId', null,
        'revocationReason', p_revocation_reason
      );
      result := jsonb_build_object(
        'status', result_status, 'grantId', result_grant_id,
        'targetUserId', p_target_user_id, 'moduleKey', p_module_key,
        'permissionKey', p_permission_key, 'resourceType', null, 'resourceId', null
      );
    end if;
  end if;

  insert into public.module_grant_operations (
    operation_id, action, actor_user_id, actor_device_id,
    target_user_id, module_key, permission_key, resource_type, resource_id,
    requested_grant_id, resulting_grant_id, revocation_reason,
    authority_source, authority_grant_id, intent_hash, outcome, stored_result
  ) values (
    p_operation_id, p_action, actor_id, p_actor_device_id,
    p_target_user_id, p_module_key, p_permission_key, null, null,
    p_grant_id, result_grant_id, p_revocation_reason,
    authority_source, authority_grant_id, intent, result_status, result
  );

  if result_status in ('created', 'revoked') then
    insert into public.module_grant_audit_log (
      event_type, actor_user_id, actor_device_id, target_user_id,
      module_key, permission_key, resource_type, resource_id,
      grant_id, authority_source, authority_grant_id, operation_id,
      old_values, new_values
    ) values (
      case when result_status = 'created' then 'grant_created' else 'grant_revoked' end,
      actor_id, p_actor_device_id, p_target_user_id,
      p_module_key, p_permission_key, null, null,
      result_grant_id, authority_source, authority_grant_id, p_operation_id,
      old_values, new_values
    );
  end if;
  return result;
end;
$$;

-- Round 3G.2: protected module-permission administration reads and catalog grant transport.

create or replace function public.search_module_permission_candidates(
  p_actor_device_id uuid,
  p_module_key text,
  p_query text default null,
  p_limit integer default 50
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare
  actor_id uuid;
  normalized_query text := lower(btrim(coalesce(p_query, '')));
  effective_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
begin
  actor_id := public.require_current_approved_device(p_actor_device_id);
  if not exists (
    select 1 from public.platform_modules modules
     where modules.module_key = p_module_key and modules.status = 'active'
  ) then
    raise exception 'ACTIVE_MODULE_REQUIRED' using errcode = '42501';
  end if;
  if not public.is_system_owner(actor_id) then
    perform public.require_module_permission(
      p_actor_device_id, p_module_key, 'module.manage', null, null
    );
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'userId', candidates.id,
      'displayName', candidates.display_name,
      'email', candidates.email,
      'accountStatus', candidates.account_status
    ) order by coalesce(candidates.display_name, candidates.email), candidates.id)
    from (
      select users.id, profiles.display_name, users.email, access.account_status
        from auth.users users
        join public.system_user_access access on access.user_id = users.id
        left join public.profiles profiles on profiles.id = users.id
       where access.account_status = 'approved'
         and (
           normalized_query = ''
           or lower(coalesce(profiles.display_name, '')) like '%' || normalized_query || '%'
           or lower(coalesce(users.email, '')) like '%' || normalized_query || '%'
         )
       order by coalesce(profiles.display_name, users.email), users.id
       limit effective_limit
    ) candidates
  ), '[]'::jsonb);
end;
$$;

create or replace function public.list_module_permission_catalog_for_administration(
  p_actor_device_id uuid,
  p_module_key text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
declare actor_id uuid;
begin
  actor_id := public.require_current_approved_device(p_actor_device_id);
  if not exists (
    select 1 from public.platform_modules modules
     where modules.module_key = p_module_key and modules.status = 'active'
  ) then
    raise exception 'ACTIVE_MODULE_REQUIRED' using errcode = '42501';
  end if;
  if not public.is_system_owner(actor_id) then
    perform public.require_module_permission(
      p_actor_device_id, p_module_key, 'module.manage', null, null
    );
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'permissionKey', catalog.permission_key,
      'displayName', catalog.display_name,
      'description', catalog.description,
      'allowedScopeMode', catalog.allowed_scope_mode,
      'allowedResourceType', catalog.allowed_resource_type,
      'sensitiveMutation', catalog.sensitive_mutation,
      'catalogVersion', catalog.catalog_version
    ) order by catalog.permission_key)
      from public.module_permission_catalog catalog
     where catalog.module_key = p_module_key
       and catalog.status = 'active'
       and catalog.permission_key not in ('module.access', 'module.manage')
       and catalog.permission_key not like 'module.%'
  ), '[]'::jsonb);
end;
$$;

create or replace function warehouse.list_permission_administration_stores(
  p_device_id uuid,
  p_include_inactive boolean default false
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, warehouse
as $$
declare actor_id uuid;
begin
  actor_id := public.require_current_approved_device(p_device_id);
  if not exists (
    select 1 from public.platform_modules modules
     where modules.module_key = 'warehouse' and modules.status = 'active'
  ) then
    raise exception 'ACTIVE_MODULE_REQUIRED' using errcode = '42501';
  end if;
  if not public.is_system_owner(actor_id) then
    perform public.require_module_permission(
      p_device_id, 'warehouse', 'module.manage', null, null
    );
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'storeId', stores.id,
      'code', stores.code,
      'name', stores.name,
      'status', stores.status
    ) order by stores.code, stores.id)
      from warehouse.stores stores
     where coalesce(p_include_inactive, false) or stores.status = 'active'
  ), '[]'::jsonb);
end;
$$;

revoke all on function public.search_module_permission_candidates(uuid,text,text,integer) from public, anon, authenticated;
revoke all on function public.list_module_permission_catalog_for_administration(uuid,text) from public, anon, authenticated;
revoke all on function warehouse.list_permission_administration_stores(uuid,boolean) from public, anon, authenticated;
grant execute on function public.search_module_permission_candidates(uuid,text,text,integer) to service_role;
grant execute on function public.list_module_permission_catalog_for_administration(uuid,text) to service_role;
grant execute on function warehouse.list_permission_administration_stores(uuid,boolean) to service_role;

alter function platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)
  rename to execute_device_operation_pre_module_permission_administration;

create function platform.execute_device_operation(
  p_user_id uuid,
  p_session_id uuid,
  p_token_hash bytea,
  p_module text,
  p_operation text,
  p_args jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, platform, platform_private, warehouse
as $$
declare session platform_private.device_sessions%rowtype;
begin
  if not (
    (p_module = 'conference' and p_operation in (
      'search_module_permission_candidates',
      'list_module_permission_catalog_for_administration',
      'manage_catalog_module_grant'
    ))
    or (p_module = 'warehouse' and p_operation = 'list_permission_administration_stores')
  ) then
    return platform.execute_device_operation_pre_module_permission_administration(
      p_user_id, p_session_id, p_token_hash, p_module, p_operation, p_args
    );
  end if;
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'PLATFORM_OPERATION_BACKEND_REQUIRED' using errcode = '42501';
  end if;
  if p_args is null or jsonb_typeof(p_args) <> 'object'
     or p_args ? 'p_actor_device_id' or p_args ? 'p_device_id' then
    raise exception 'PLATFORM_OPERATION_ARGUMENT_INVALID' using errcode = '22023';
  end if;

  select item.* into session
    from platform_private.device_sessions item
    join platform.device_key_bindings binding on binding.id = item.binding_id
    join platform.user_device_authorizations uda on uda.id = item.device_authorization_id
    join platform.devices device on device.id = item.device_id
    join platform.profiles profile on profile.user_id = item.user_id
   where item.id = p_session_id and item.user_id = p_user_id and item.token_hash = p_token_hash
     and item.purpose = 'PLATFORM_DEVICE_SESSION' and item.revoked_at is null
     and item.expires_at > statement_timestamp()
     and binding.user_id = item.user_id and binding.device_id = item.device_id
     and binding.device_authorization_id = item.device_authorization_id
     and binding.public_key_thumbprint = item.public_key_thumbprint
     and binding.algorithm = 'ECDSA_P256_SHA256' and binding.lifecycle_status = 'active'
     and binding.revoked_at is null and binding.retired_at is null
     and uda.user_id = item.user_id and uda.device_id = item.device_id
     and uda.status = 'approved' and uda.revoked_at is null
     and device.lifecycle_status = 'active' and device.retired_at is null
     and device.compromised_at is null and profile.account_status = 'approved';
  if not found then
    raise exception 'DEVICE_SESSION_INVALID' using errcode = '42501';
  end if;
  perform set_config('request.jwt.claims', jsonb_build_object(
    'sub', p_user_id, 'role', 'service_role'
  )::text, true);
  perform set_config('platform.phase1c_context', jsonb_build_object(
    'purpose', 'PLATFORM_DEVICE_SESSION_DISPATCH', 'session_id', session.id,
    'user_id', session.user_id, 'device_id', session.device_id,
    'authorization_id', session.device_authorization_id, 'binding_id', session.binding_id,
    'token_hash', encode(p_token_hash, 'hex')
  )::text, true);

  if p_operation = 'search_module_permission_candidates' then
    perform platform_private.require_exact_jsonb_keys(p_args, array['p_module_key','p_query','p_limit']);
    return public.search_module_permission_candidates(session.device_id, p_args->>'p_module_key', p_args->>'p_query', (p_args->>'p_limit')::integer);
  elsif p_operation = 'list_module_permission_catalog_for_administration' then
    perform platform_private.require_exact_jsonb_keys(p_args, array['p_module_key']);
    return public.list_module_permission_catalog_for_administration(session.device_id, p_args->>'p_module_key');
  elsif p_operation = 'manage_catalog_module_grant' then
    perform platform_private.require_exact_jsonb_keys(p_args, array['p_operation_id','p_action','p_target_user_id','p_module_key','p_permission_key','p_resource_type','p_resource_id','p_grant_id','p_revocation_reason']);
    return public.manage_catalog_module_grant(
      session.device_id, (p_args->>'p_operation_id')::uuid, p_args->>'p_action',
      (p_args->>'p_target_user_id')::uuid, p_args->>'p_module_key', p_args->>'p_permission_key',
      p_args->>'p_resource_type', p_args->>'p_resource_id', (p_args->>'p_grant_id')::uuid,
      p_args->>'p_revocation_reason'
    );
  end if;

  perform platform_private.require_exact_jsonb_keys(p_args, array['p_include_inactive']);
  return warehouse.list_permission_administration_stores(
    session.device_id, (p_args->>'p_include_inactive')::boolean
  );
end;
$$;

